mapper.select:
SELECT /*selectExportExBlExportBlProcList*/ HD.BUYER , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = HD.BUYER) AS BUYER_NM , HD.AGENT , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = HD.AGENT) AS AGENT_NM , HD.CI_NO , HD.CI_DATE , HD.PKG_COMPANY_CODE , HD.TOTAL_WEIGHT AS GROSS_WEIGHT , HD.PACKING_UNIT , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'EP05' AND COD.CODE = HD.PACKING_UNIT) AS PCKING_UNIT_NM , HD.PACKING_WEIGHT , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'EP06' AND COD.CODE = HD.PACKING_WEIGHT) AS PACKING_WEIGHT_NM , HD.FORWARDER , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'EP01' AND COD.CODE = HD.FORWARDER) AS FORWARDER_NM , HD.CURRENCY_CODE , HD.ITEM_AMT , TO_CHAR(HD.ADD_DATE,'YYYYMMDD') AS ADD_DATE , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = HD.ADD_USER_ID) AS ADD_USER_NM , HD.ADD_USER_ID , '1' AS CI_SHEET , '1' AS PL_SHEET , HD.NOTIFY_PARTY , HD.SHIP_METHOD ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'EP02' AND CODE = HD.SHIP_METHOD) AS SHIP_METHOD_NM , HD.PORT_OF_LOADING , HD.FINAL_DESTINATION , (SELECT TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE = 'POTD' AND COD.CODE =HD.PORT_OF_LOADING) AS PORT_OF_LOADING_NM , (SELECT TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE = 'POTA' AND COD.CODE =HD.FINAL_DESTINATION) AS FINAL_DESTINATION_NM FROM KEP_EXP_CIHD HD WHERE HD.STATUS != 'D' AND HD.BL_COMPLETE_MARK = 'N' AND HD.PKG_COMPANY_CODE =#{st_pkg_cmpy_no} AND HD.CI_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND HD.BUYER IN
#{item}
AND HD.AGENT = #{st_agent_code}
AND HD.CI_NO LIKE #{st_ci_no}||'%'
ORDER BY HD.BUYER, HD.CI_NO

mapper.update:

/*insertExportExBlKepExpBlDt*/
INSERT INTO KEP_EXP_BLDT(
	 BUYER
	 ,PKG_COMPANY_CODE
	 ,BL_NO
	 ,BL_SEQ
	 ,CI_NO
	 ,STATUS
	 ,ADD_DATE
	 ,ADD_USER_ID
	 ,CHANGE_DATE
	 ,CHANGE_USER_ID
) VALUES (
		  #{st_buyer}
		, #{st_pkg_cmpy_no}
		, UPPER(#{st_bl_no})
		, TO_CHAR( #{BL_SEQ}, 'FM000000')
		, #{CI_NO}
		, 'C'
		, SYSDATE
		, #{st_user_id}
		, SYSDATE
		, #{st_user_id}
)


	/*updateExportExBlKepExpCiDt*/
 	UPDATE KEP_EXP_CIHD HD
 	SET BL_COMPLETE_MARK = 'Y'
 	, STATUS = 'R'
 	, CHANGE_DATE = SYSDATE
 	, CHANGE_USER_ID = #{st_user_id}
 	WHERE  HD.PKG_COMPANY_CODE = #{st_pkg_cmpy_no} 
 	AND HD.CI_NO = #{CI_NO}


/*insertExportExBlKepExpBlHd*/
INSERT INTO KEP_EXP_BLHD(
	 BUYER
	 ,PKG_COMPANY_CODE
	 ,BL_NO
	 ,STATUS
	 ,DEPARTURE_PORT
	 ,BL_ISSUE_DATE
	 ,SHIPPER
	 ,ETD_DATE
	 ,SHIPPING_METHOD
	 ,CHARGABLE_WEIGHT
	 ,FLIGHT_VESSEL_NO
	 ,DESTINATION_PORT
	 ,ON_BOARD_DATE
	 ,CONSIGNEES
	 ,ETA_DATE
	 ,MASTER_BL_NO
	 ,CARRIER
	 ,IMAGE_KEY
	 ,ADD_DATE
	 ,ADD_USER_ID
	 ,CHANGE_DATE
	 ,CHANGE_USER_ID
	 ,DEPARTURE_PORT_CODE
	 ,DESTINATION_PORT_CODE
) VALUES (
		  #{st_buyer}
		, #{st_pkg_cmpy_no}
		, UPPER(#{st_bl_no})
		, 'C'
		, (SELECT TEXT1 FROM ICOMCOD2 COD
			WHERE COD.TYPE = 'POTD'
			AND COD.CODE =#{st_departure})
		, #{st_issue_date}
		, #{st_shipper}
		, #{st_etd_date}||#{st_etd_hour}||#{st_etd_minute}
		, #{st_ship_method}
		, #{st_charg}
		, #{st_f_v_no}
		, (SELECT TEXT1 FROM ICOMCOD2 COD
			WHERE COD.TYPE = 'POTA'
			AND COD.CODE =#{st_destination})
		, #{st_board_date}
		, #{st_con}
		, #{st_eta_date}||#{st_eta_hour}||#{st_eta_minute}
		, UPPER(#{st_master_bl})
		, #{st_carrier}
		, #{st_image_key}
		, SYSDATE
		, #{st_user_id}
		, SYSDATE
		, #{st_user_id}
		, #{st_departure}
		, #{st_destination}
)
